VALUES ('doc-09-mitre-attack-p0-19448', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-30T18:56:48.918Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Derusbi](https://attack.mitre.org/software/S0021) has used unencrypted HTTP on port 443 for C2.(Citation: Fidelis Turbo)", "external_references": [{"description": "Fidelis Cybersecurity. (2016, February 29). The Turbo Campaign, Featuring Derusbi for 64-bit Linux. Retrieved March 2, 2016.", "source_name": "Fidelis Turbo", "url": "https://paper.seebug.org/papers/APT/APT_CyberCriminal_Campagin/2016/2016.02.29.Turbo_Campaign_Derusbi/TA_Fidelis_Turbo_1602_0.pdf"}], "id": "relationship--a5bb3ddf-446a-42c4-b522-112ad643c678", "modified": "2026-04-29T14:23:06.151Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--94379dec-5c87-49db-b36e-66abc0b81344", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19448', 0, 65, '09-mitre-attack', 'retrieved', 'AE6A8EE10B9C24B63030D579C1E959F24E3C1F3ADC4F32741A1F1A326104FCB8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
