VALUES ('doc-09-mitre-attack-p0-19449', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Derusbi](https://attack.mitre.org/software/S0021) obfuscates C2 traffic with variable 4-byte XOR keys.(Citation: Fidelis Turbo)", "external_references": [{"description": "Fidelis Cybersecurity. (2016, February 29). The Turbo Campaign, Featuring Derusbi for 64-bit Linux. Retrieved March 2, 2016.", "source_name": "Fidelis Turbo", "url": "https://paper.seebug.org/papers/APT/APT_CyberCriminal_Campagin/2016/2016.02.29.Turbo_Campaign_Derusbi/TA_Fidelis_Turbo_1602_0.pdf"}], "id": "relationship--a7cb0193-e854-4361-b1a1-fc4e68354c59", "modified": "2026-04-29T14:23:06.154Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--94379dec-5c87-49db-b36e-66abc0b81344", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19449', 0, 64, '09-mitre-attack', 'retrieved', '561CC7FD0776EC0EEC052E1E54ACF7D934DBDB9ADFA91731F1BF7555DD99C8FC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
