VALUES ('doc-09-mitre-attack-p0-19470', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-17T01:39:58.900Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BlackByte Ransomware](https://attack.mitre.org/software/S1180) adds .JS and .EXE extensions to the Microsoft Defender exclusion list. [BlackByte Ransomware](https://attack.mitre.org/software/S1180) terminates and removes the Raccine anti-ransomware utility.(Citation: Trustwave BlackByte 2021)", "external_references": [{"description": "Rodel Mendrez & Lloyd Macrohon. (2021, October 15). BlackByte Ransomware – Pt. 1 In-depth Analysis. Retrieved December 16, 2024.", "source_name": "Trustwave BlackByte 2021", "url": "https://www.trustwave.com/en-us/resources/blogs/spiderlabs-blog/blackbyte-ransomware-pt-1-in-depth-analysis/"}], "id": "relationship--9fa5ea79-2064-4a07-903b-b00987ac2c8a", "modified": "2026-04-29T14:23:06.143Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9454bb5d-3bdb-40f9-a878-b5fb446ded3d", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19470', 0, 81, '09-mitre-attack', 'retrieved', 'A076C5EEE8968201D96074AD12D62883831FFA053C65E4A8A06E17C076781841', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
