VALUES ('doc-09-mitre-attack-p0-19471', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-17T01:47:19.531Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BlackByte Ransomware](https://attack.mitre.org/software/S1180) uses the `SetThreadExecutionState` API to prevent the victim system from entering sleep.(Citation: Trustwave BlackByte 2021)", "external_references": [{"description": "Rodel Mendrez & Lloyd Macrohon. (2021, October 15). BlackByte Ransomware – Pt. 1 In-depth Analysis. Retrieved December 16, 2024.", "source_name": "Trustwave BlackByte 2021", "url": "https://www.trustwave.com/en-us/resources/blogs/spiderlabs-blog/blackbyte-ransomware-pt-1-in-depth-analysis/"}], "id": "relationship--c3cf7bd6-e8cf-4800-a7eb-82a8b1fcb14d", "modified": "2026-04-29T14:23:06.193Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9454bb5d-3bdb-40f9-a878-b5fb446ded3d", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19471', 0, 73, '09-mitre-attack', 'retrieved', '30997594712179A65D6B5E5C2C5575CFB2848FA99088CC1F5A488A5E8EF41074', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
