VALUES ('doc-09-mitre-attack-p0-19472', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-17T01:53:25.369Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BlackByte Ransomware](https://attack.mitre.org/software/S1180) uses the `mountvol.exe` command to mount volume names and leverages the Microsoft Discretionary Access Control List tool, `icacls.exe`, to grant the group to “Everyone” full access to the root of the drive.(Citation: Trustwave BlackByte 2021)", "external_references": [{"description": "Rodel Mendrez & Lloyd Macrohon. (2021, October 15). BlackByte Ransomware – Pt. 1 In-depth Analysis. Retrieved December 16, 2024.", "source_name": "Trustwave BlackByte 2021", "url": "https://www.trustwave.com/en-us/resources/blogs/spiderlabs-blog/blackbyte-ransomware-pt-1-in-depth-analysis/"}], "id": "relationship--c4f36a8a-6118-4486-8298-54e5b01b76d5", "modified": "2026-04-29T14:23:06.194Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9454bb5d-3bdb-40f9-a878-b5fb446ded3d", "spec_version": "2.1", "target_ref": "attack-pattern--34e793de-0274-4982-9c1a-246ed1c19dee", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19472', 0, 93, '09-mitre-attack', 'retrieved', '7AA615CC12AE1D52748F39F939EF324AF5A640358CCF5FE58EA325A3528D8ABE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
