VALUES ('doc-09-mitre-attack-p0-19509', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T16:33:46.445Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StrelaStealer](https://attack.mitre.org/software/S1183) exfiltrates collected email credentials via HTTP POST to command and control servers.(Citation: DCSO StrelaStealer 2022)(Citation: PaloAlto StrelaStealer 2024)(Citation: Fortgale StrelaStealer 2023)(Citation: IBM StrelaStealer 2024)", "external_references": [{"description": "Benjamin Chang, Goutam Tripathy, Pranay Kumar Chhaparwal, Anmol Maurya & Vishwa Thothathri, Palo Alto Networks. (2024, March 22). Large-Scale StrelaStealer Campaign in Early 2024. Retrieved December 31, 2024.", "source_name": "PaloAlto StrelaStealer 2024", "url": "https://unit42.paloaltonetworks.com/strelastealer-campaign/"}, {"description": "DCSO CyTec Blog. (2022, November 8). #ShortAndMalicious: StrelaStealer aims for mail credentials. Retrieved December 31, 2024.", "source_name": "DCSO StrelaStealer 2022", "url": "https://medium.com/@DCSO_CyTec/shortandmalicious-strelastealer-aims-for-mail-credentials-a4c3e78c8abc"}, {"description": "Fortgale. (2023, September 18). StrelaStealer Malware Analysis. Retrieved December 31, 2024.", "source_name": "Fortgale StrelaStealer 2023", "url": "https://fortgale.com/blog/malware-analysis/strelastealer-malware-analysis-2/"}, {"description": "Golo Mühr, Joe Fasulo & Charlotte Hammond, IBM X-Force. (2024, November 12). Strela Stealer: Today’s invoice is tomorrow’s phish. Retrieved December 31, 2024.", "source_name": "IBM StrelaStealer 2024", "url": "https://securityintelligence.com/x-force/strela-stealer-todays-invoice-tomorrows-phish/"}], "id": "relationship--0e08fbc4-2fe5-4761-8f70-3dc74af48a57", "modified": "2026-04-29T14:23:05.922Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--951313b3-6064-4ce0-b4b6-a153c3973da7", "spec_version": "2.1", "target_ref": "attack-pattern--92d7da27-2d91-488e-a00c-059dc162766d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19509', 0, 161, '09-mitre-attack', 'retrieved', '6F3BBDF7361D752A662E6341DB5ACA5183398167C1569F2387904531DD224F84', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
