VALUES ('doc-09-mitre-attack-p0-19516', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T16:18:53.134Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StrelaStealer](https://attack.mitre.org/software/S1183) has used a renamed, legitimate `msinfo32.exe` executable to sideload the [StrelaStealer](https://attack.mitre.org/software/S1183) payload during initial installation.(Citation: DCSO StrelaStealer 2022)", "external_references": [{"description": "DCSO CyTec Blog. (2022, November 8). #ShortAndMalicious: StrelaStealer aims for mail credentials. Retrieved December 31, 2024.", "source_name": "DCSO StrelaStealer 2022", "url": "https://medium.com/@DCSO_CyTec/shortandmalicious-strelastealer-aims-for-mail-credentials-a4c3e78c8abc"}], "id": "relationship--3971fa3e-6ed3-4bc0-84d6-115431ac8d96", "modified": "2026-04-29T14:23:05.999Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--951313b3-6064-4ce0-b4b6-a153c3973da7", "spec_version": "2.1", "target_ref": "attack-pattern--bd5b58a4-a52d-4a29-bc0d-3f1d3968eb6b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19516', 0, 72, '09-mitre-attack', 'retrieved', '03883F3B9913F659BFB9FF6C5405470EC3EC8562317114BD5822B96F4186F838', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
