VALUES ('doc-09-mitre-attack-p0-19534', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T16:24:47.009Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StrelaStealer](https://attack.mitre.org/software/S1183) payloads have included strings encrypted via XOR.(Citation: DCSO StrelaStealer 2022) [StrelaStealer](https://attack.mitre.org/software/S1183) JavaScript payloads utilize Base64-encoded payloads that are decoded via [certutil](https://attack.mitre.org/software/S0160) to create a malicious DLL file.(Citation: PaloAlto StrelaStealer 2024)(Citation: Fortgale StrelaStealer 2023)", "external_references": [{"description": "Benjamin Chang, Goutam Tripathy, Pranay Kumar Chhaparwal, Anmol Maurya & Vishwa Thothathri, Palo Alto Networks. (2024, March 22). Large-Scale StrelaStealer Campaign in Early 2024. Retrieved December 31, 2024.", "source_name": "PaloAlto StrelaStealer 2024", "url": "https://unit42.paloaltonetworks.com/strelastealer-campaign/"}, {"description": "DCSO CyTec Blog. (2022, November 8). #ShortAndMalicious: StrelaStealer aims for mail credentials. Retrieved December 31, 2024.", "source_name": "DCSO StrelaStealer 2022", "url": "https://medium.com/@DCSO_CyTec/shortandmalicious-strelastealer-aims-for-mail-credentials-a4c3e78c8abc"}, {"description": "Fortgale. (2023, September 18). StrelaStealer Malware Analysis. Retrieved December 31, 2024.", "source_name": "Fortgale StrelaStealer 2023", "url": "https://fortgale.com/blog/malware-analysis/strelastealer-malware-analysis-2/"}], "id": "relationship--c948844f-25f3-4fbd-b949-f6c61a459aeb", "modified": "2026-04-29T14:23:06.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--951313b3-6064-4ce0-b4b6-a153c3973da7", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_versi