VALUES ('doc-09-mitre-attack-p0-19537', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T21:49:07.848Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StrelaStealer](https://attack.mitre.org/software/S1183) variants collect victim system information for exfiltration.(Citation: IBM StrelaStealer 2024)", "external_references": [{"description": "Golo Mühr, Joe Fasulo & Charlotte Hammond, IBM X-Force. (2024, November 12). Strela Stealer: Today’s invoice is tomorrow’s phish. Retrieved December 31, 2024.", "source_name": "IBM StrelaStealer 2024", "url": "https://securityintelligence.com/x-force/strela-stealer-todays-invoice-tomorrows-phish/"}], "id": "relationship--de9ac4ba-9e06-4704-9549-b3c59882bdb2", "modified": "2026-04-29T14:23:06.229Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--951313b3-6064-4ce0-b4b6-a153c3973da7", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19537', 0, 71, '09-mitre-attack', 'retrieved', 'C91ED59E6A933B04DFC4E5D215425735885EA76949244B95A5319AE571381DDD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
