VALUES ('doc-09-mitre-attack-p0-19538', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-31T16:27:25.484Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StrelaStealer](https://attack.mitre.org/software/S1183) searches for and if found collects the contents of files such as `logins.json` and `key4.db` in the `$APPDATA%\\Thunderbird\\Profiles\\` directory, associated with the Thunderbird email application.(Citation: DCSO StrelaStealer 2022)(Citation: Fortgale StrelaStealer 2023)", "external_references": [{"description": "DCSO CyTec Blog. (2022, November 8). #ShortAndMalicious: StrelaStealer aims for mail credentials. Retrieved December 31, 2024.", "source_name": "DCSO StrelaStealer 2022", "url": "https://medium.com/@DCSO_CyTec/shortandmalicious-strelastealer-aims-for-mail-credentials-a4c3e78c8abc"}, {"description": "Fortgale. (2023, September 18). StrelaStealer Malware Analysis. Retrieved December 31, 2024.", "source_name": "Fortgale StrelaStealer 2023", "url": "https://fortgale.com/blog/malware-analysis/strelastealer-malware-analysis-2/"}], "id": "relationship--deddda4d-6ce3-4531-aaea-b7b049597a22", "modified": "2026-04-29T14:23:06.229Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--951313b3-6064-4ce0-b4b6-a153c3973da7", "spec_version": "2.1", "target_ref": "attack-pattern--837f9164-50af-4ac0-8219-379d8a74cefc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19538', 0, 103, '09-mitre-attack', 'retrieved', 'F350BFA96297AE4E5F95C16A6ED56AC10E995CFAE787E1B71ADB88555834B652', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
