VALUES ('doc-09-mitre-attack-p0-19616', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sakula](https://attack.mitre.org/software/S0074) calls cmd.exe to run various DLL files via rundll32 and also to perform file cleanup. [Sakula](https://attack.mitre.org/software/S0074) also has the capability to invoke a reverse shell.(Citation: Dell Sakula)", "external_references": [{"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, July 30). Sakula Malware Family. Retrieved January 26, 2016.", "source_name": "Dell Sakula", "url": "http://www.secureworks.com/cyber-threat-intelligence/threats/sakula-malware-family/"}], "id": "relationship--a3fe1f58-b507-42ea-a21e-a6ac46de9ca8", "modified": "2026-04-29T14:23:06.148Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--96b08451-b27a-4ff6-893f-790e26393a8e", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19616', 0, 81, '09-mitre-attack', 'retrieved', '1C48A47A57053EA3F44DDC17ED647F8536CF756A0EBCC65AEDE8CF204BAB52BE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
