VALUES ('doc-09-mitre-attack-p0-19625', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RawPOS](https://attack.mitre.org/software/S0169) encodes credit card data it collected from the victim with XOR.(Citation: TrendMicro RawPOS April 2015)(Citation: Mandiant FIN5 GrrCON Oct 2016)(Citation: Visa RawPOS March 2015)", "external_references": [{"description": "TrendLabs Security Intelligence Blog. (2015, April). RawPOS Technical Brief. Retrieved October 4, 2017.", "source_name": "TrendMicro RawPOS April 2015", "url": "http://sjc1-te-ftp.trendmicro.com/images/tex/pdf/RawPOS%20Technical%20Brief.pdf"}, {"description": "Bromiley, M. and Lewis, P. (2016, October 7). Attacking the Hospitality and Gaming Industries: Tracking an Attacker Around the World in 7 Years. Retrieved October 6, 2017.", "source_name": "Mandiant FIN5 GrrCON Oct 2016", "url": "https://www.youtube.com/watch?v=fevGZs0EQu8"}, {"description": "Visa. (2015, March). Visa Security Alert: \"RawPOS\" Malware Targeting Lodging Merchants. Retrieved October 6, 2017.", "source_name": "Visa RawPOS March 2015", "url": "https://usa.visa.com/dam/VCOM/download/merchants/alert-rawpos.pdf"}], "id": "relationship--53ad6525-7888-4651-bd43-c010b489ccc0", "modified": "2026-04-29T14:23:06.039Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9752aef4-a1f3-4328-929f-b64eb0536090", "spec_version": "2.1", "target_ref": "attack-pattern--143c0cbb-a297-4142-9624-87ffc778980b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19625', 0, 135, '09-mitre-attack', 'retrieved', 'A2A3E2F34D64A05B12B1E667AAF300104A6CDE852E7B559820AB0F355A8983DE', 'v1', '{"source_id": "0