VALUES ('doc-09-mitre-attack-p0-19770', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-25T21:30:06.347Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kobalos](https://attack.mitre.org/software/S0641) can write captured SSH connection credentials to a file under the /var/run directory with a .pid extension for exfiltration.(Citation: ESET Kobalos Jan 2021) ", "external_references": [{"description": "M.Leveille, M., Sanmillan, I. (2021, January). A WILD KOBALOS APPEARS Tricksy Linux malware goes after HPCs. Retrieved August 24, 2021.", "source_name": "ESET Kobalos Jan 2021", "url": "https://www.welivesecurity.com/wp-content/uploads/2021/01/ESET_Kobalos.pdf"}], "id": "relationship--773e62aa-8b0a-4ed2-9954-1886c789e926", "modified": "2026-04-29T14:23:06.088Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9abdda30-08e0-4ab1-9cf0-d447654c6de9", "spec_version": "2.1", "target_ref": "attack-pattern--7dd95ff6-712e-4056-9626-312ea4ab4c5e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19770', 0, 83, '09-mitre-attack', 'retrieved', '5610E025768FCBB0C157C82F6A1EBDBB554F114C9CB3B8C9446FC5165A8CCC48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
