VALUES ('doc-09-mitre-attack-p0-19773', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-24T20:03:36.001Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kobalos](https://attack.mitre.org/software/S0641)''s post-authentication communication channel uses a 32-byte-long password with RC4 for inbound and outbound traffic.(Citation: ESET Kobalos Feb 2021)(Citation: ESET Kobalos Jan 2021) ", "external_references": [{"description": "M.Leveille, M., Sanmillan, I. (2021, February 2). Kobalos – A complex Linux threat to high performance computing infrastructure. Retrieved August 24, 2021.", "source_name": "ESET Kobalos Feb 2021", "url": "https://www.welivesecurity.com/2021/02/02/kobalos-complex-linux-threat-high-performance-computing-infrastructure/"}, {"description": "M.Leveille, M., Sanmillan, I. (2021, January). A WILD KOBALOS APPEARS Tricksy Linux malware goes after HPCs. Retrieved August 24, 2021.", "source_name": "ESET Kobalos Jan 2021", "url": "https://www.welivesecurity.com/wp-content/uploads/2021/01/ESET_Kobalos.pdf"}], "id": "relationship--8d75c103-c7d8-44cd-afb6-f36f763c031f", "modified": "2026-04-29T14:23:06.118Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9abdda30-08e0-4ab1-9cf0-d447654c6de9", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19773', 0, 112, '09-mitre-attack', 'retrieved', '50BB1709559FF2E0AF2FAED4593F9F78FE8C11790D1C496CDFEDFD072895BE1D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
