VALUES ('doc-09-mitre-attack-p0-19774', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-24T20:03:35.975Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kobalos](https://attack.mitre.org/software/S0641) can exfiltrate credentials over the network via UDP.(Citation: ESET Kobalos Jan 2021)", "external_references": [{"description": "M.Leveille, M., Sanmillan, I. (2021, January). A WILD KOBALOS APPEARS Tricksy Linux malware goes after HPCs. Retrieved August 24, 2021.", "source_name": "ESET Kobalos Jan 2021", "url": "https://www.welivesecurity.com/wp-content/uploads/2021/01/ESET_Kobalos.pdf"}], "id": "relationship--91cd43d9-17cb-41d3-b62d-4b79030f4384", "modified": "2026-04-29T14:23:06.124Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9abdda30-08e0-4ab1-9cf0-d447654c6de9", "spec_version": "2.1", "target_ref": "attack-pattern--a19e86f8-1c0a-4fea-8407-23b73d615776", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19774', 0, 71, '09-mitre-attack', 'retrieved', '9F13DC079158E7D090D852648218AA2050C67F858542D2C9AF8AAF3A0E2D34E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
