VALUES ('doc-09-mitre-attack-p0-19775', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-24T22:12:46.625Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kobalos](https://attack.mitre.org/software/S0641) can modify timestamps of replaced files, such as ssh with the added credential stealer or sshd used to deploy [Kobalos](https://attack.mitre.org/software/S0641).(Citation: ESET Kobalos Jan 2021) ", "external_references": [{"description": "M.Leveille, M., Sanmillan, I. (2021, January). A WILD KOBALOS APPEARS Tricksy Linux malware goes after HPCs. Retrieved August 24, 2021.", "source_name": "ESET Kobalos Jan 2021", "url": "https://www.welivesecurity.com/wp-content/uploads/2021/01/ESET_Kobalos.pdf"}], "id": "relationship--9bbfc21c-17ab-4f9a-bd8c-5079ee9b180f", "modified": "2026-04-29T14:23:06.137Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9abdda30-08e0-4ab1-9cf0-d447654c6de9", "spec_version": "2.1", "target_ref": "attack-pattern--47f2d673-ca62-47e9-929b-1b0be9657611", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19775', 0, 84, '09-mitre-attack', 'retrieved', 'CE96F5448ADEE2D30858F7EEB2676B3742CF863F1AC6B89CBC4BEE70D8EA5BBC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
