VALUES ('doc-09-mitre-attack-p0-19791', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T21:33:34.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BadPatch](https://attack.mitre.org/software/S0337) uses WMI to enumerate installed security products in the victim’s environment.(Citation: Unit 42 BadPatch Oct 2017)", "external_references": [{"description": "Bar, T., Conant, S. (2017, October 20). BadPatch. Retrieved November 13, 2018.", "source_name": "Unit 42 BadPatch Oct 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/10/unit42-badpatch/"}], "id": "relationship--c443cc21-5f8f-4c12-8848-39c469a1c9b2", "modified": "2026-04-29T14:23:06.193Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9af05de0-bc09-4511-a350-5eb8b06185c1", "spec_version": "2.1", "target_ref": "attack-pattern--cba37adb-d6fb-4610-b069-dd04c0643384", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19791', 0, 68, '09-mitre-attack', 'retrieved', '1B37734634AA28BEB4EB9FE2D1B12D39B6CD32B212AAA7FC7356AE4BFB3DA35F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
