VALUES ('doc-09-mitre-attack-p0-19792', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T21:33:34.658Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BadPatch](https://attack.mitre.org/software/S0337) collects files from the local system that have the following extensions, then prepares them for exfiltration: .xls, .xlsx, .pdf, .mdb, .rar, .zip, .doc, .docx.(Citation: Unit 42 BadPatch Oct 2017)", "external_references": [{"description": "Bar, T., Conant, S. (2017, October 20). BadPatch. Retrieved November 13, 2018.", "source_name": "Unit 42 BadPatch Oct 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/10/unit42-badpatch/"}], "id": "relationship--dc2b58dd-1052-4860-8e14-5650ab8eecfd", "modified": "2026-04-29T14:23:06.226Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9af05de0-bc09-4511-a350-5eb8b06185c1", "spec_version": "2.1", "target_ref": "attack-pattern--3c4a2599-71ee-4405-ba1e-0e28414b4bc5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19792', 0, 81, '09-mitre-attack', 'retrieved', '65B2CB7F80E8FA614F6B25757845A1D0261ABFD8AE9ADD8990312541C6DC383D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
