VALUES ('doc-09-mitre-attack-p0-19793', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-11T22:12:28.676Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Once loaded into memory, [MESSAGETAP](https://attack.mitre.org/software/S0443) deletes the keyword_parm.txt and parm.txt configuration files from disk. (Citation: FireEye MESSAGETAP October 2019)", "external_references": [{"description": "Leong, R., Perez, D., Dean, T. (2019, October 31). MESSAGETAP: Who’s Reading Your Text Messages?. Retrieved May 11, 2020.", "source_name": "FireEye MESSAGETAP October 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/10/messagetap-who-is-reading-your-text-messages.html"}], "id": "relationship--1d90e3ef-1839-4bb8-8205-02e2461b5d55", "modified": "2026-04-29T14:23:05.945Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9b19d6b4-cfcb-492f-8ca8-8449e7331573", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19793', 0, 76, '09-mitre-attack', 'retrieved', 'F5AC97A29C4EE8D8219E7EF60E4564B03A83340F14D463FAB4008DDBE259FD29', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
