VALUES ('doc-09-mitre-attack-p0-19800', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-11T22:12:28.735Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MESSAGETAP](https://attack.mitre.org/software/S0443) checks for the existence of two configuration files (keyword_parm.txt and parm.txt) and attempts to read the files every 30 seconds.(Citation: FireEye MESSAGETAP October 2019)", "external_references": [{"description": "Leong, R., Perez, D., Dean, T. (2019, October 31). MESSAGETAP: Who’s Reading Your Text Messages?. Retrieved May 11, 2020.", "source_name": "FireEye MESSAGETAP October 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/10/messagetap-who-is-reading-your-text-messages.html"}], "id": "relationship--f9c13c35-a493-4733-b51c-ab4857692e18", "modified": "2026-04-29T14:23:06.264Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9b19d6b4-cfcb-492f-8ca8-8449e7331573", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19800', 0, 82, '09-mitre-attack', 'retrieved', 'AC7A8FC55D0C8A7508BF16A22AC2FC88A606BE90840FE8D60B7B7757BC6FF7F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
