VALUES ('doc-09-mitre-attack-p0-19840', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-11T19:48:40.672Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XLoader](https://attack.mitre.org/software/S1207) can utilize decoy command and control domains within the malware configuration to circumvent sandbox analysis.(Citation: ANY.RUN XLoader 2023)(Citation: CheckPoint XLoader 2022)", "external_references": [{"description": "Alexey Bukhteyev & Raman Ladutska, Check Point Research. (2022, May 31). XLoader Botnet: Find Me If You Can. Retrieved March 11, 2025.", "source_name": "CheckPoint XLoader 2022", "url": "https://research.checkpoint.com/2022/xloader-botnet-find-me-if-you-can/"}, {"description": "ANY.RUN. (2023, February 28). XLoader/FormBook: Encryption Analysis and Malware Decryption . Retrieved March 11, 2025.", "source_name": "ANY.RUN XLoader 2023", "url": "https://any.run/cybersecurity-blog/xloader-formbook-encryption-analysis-and-malware-decryption/"}], "id": "relationship--6ac4c8cc-c782-4749-9d22-7c5e70ff5ce0", "modified": "2026-04-29T14:23:06.070Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9c629607-03e4-4952-b481-2d54221d2783", "spec_version": "2.1", "target_ref": "attack-pattern--82caa33e-d11a-433a-94ea-9b5a5fbef81d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19840', 0, 103, '09-mitre-attack', 'retrieved', '69A8BFFFA531B52598B20E5675B7B19832B9314878857E564B76EC09B0BE0EF6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
