VALUES ('doc-09-mitre-attack-p0-19841', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-11T19:23:40.389Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XLoader](https://attack.mitre.org/software/S1207) can collect data stored in the victim''s clipboard.(Citation: Google XLoader 2017)(Citation: Netskope XLoader 2022)", "external_references": [{"description": "Gustavo Palazolo, Netskope. (2022, March 11). New Formbook Campaign Delivered Through Phishing Emails. Retrieved March 11, 2025.", "source_name": "Netskope XLoader 2022", "url": "https://www.netskope.com/blog/new-formbook-campaign-delivered-through-phishing-emails"}, {"description": "Nart Villeneuve, Randi Eitzman, Sandor Nemes & Tyler Dean, Google Cloud. (2017, October 5). Significant FormBook Distribution Campaigns Impacting the U.S. and South Korea. Retrieved March 11, 2025.", "source_name": "Google XLoader 2017", "url": "https://cloud.google.com/blog/topics/threat-intelligence/formbook-malware-distribution-campaigns/"}], "id": "relationship--6ce17afb-98fb-4b43-b99d-2eaa3c88a25e", "modified": "2026-04-29T14:23:06.073Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9c629607-03e4-4952-b481-2d54221d2783", "spec_version": "2.1", "target_ref": "attack-pattern--30973a08-aed9-4edf-8604-9084ce1b5c4f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19841', 0, 104, '09-mitre-attack', 'retrieved', '30DF0DF49C3EB0A0BC41155EE217E444E944C2FF2105A2B161D851AC696D3BA0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
