VALUES ('doc-09-mitre-attack-p0-19842', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-11T19:15:10.822Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XLoader](https://attack.mitre.org/software/S1207) uses the native Windows API for functionality, including defense evasion.(Citation: Zscaler XLoader 2025)", "external_references": [{"description": "Zscaler Threatlabz. (2025, January 27). Technical Analysis of Xloader Versions 6 and 7 | Part 1. Retrieved March 11, 2025.", "source_name": "Zscaler XLoader 2025", "url": "https://www.zscaler.com/blogs/security-research/technical-analysis-xloader-versions-6-and-7-part-1"}], "id": "relationship--859617aa-d2df-4db0-8b4a-d2be172787a6", "modified": "2026-04-29T14:23:06.108Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9c629607-03e4-4952-b481-2d54221d2783", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19842', 0, 71, '09-mitre-attack', 'retrieved', '83477A8EB1973CF1D78828AA1356B6E3C4B64C486B5BD2A04956FA1BD1EC579D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
