VALUES ('doc-09-mitre-attack-p0-19843', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-11T19:07:34.992Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XLoader](https://attack.mitre.org/software/S1207) can gather credentials from several web browsers.(Citation: Zscaler XLoader 2025)(Citation: Google XLoader 2017)(Citation: Netskope XLoader 2022)", "external_references": [{"description": "Gustavo Palazolo, Netskope. (2022, March 11). New Formbook Campaign Delivered Through Phishing Emails. Retrieved March 11, 2025.", "source_name": "Netskope XLoader 2022", "url": "https://www.netskope.com/blog/new-formbook-campaign-delivered-through-phishing-emails"}, {"description": "Nart Villeneuve, Randi Eitzman, Sandor Nemes & Tyler Dean, Google Cloud. (2017, October 5). Significant FormBook Distribution Campaigns Impacting the U.S. and South Korea. Retrieved March 11, 2025.", "source_name": "Google XLoader 2017", "url": "https://cloud.google.com/blog/topics/threat-intelligence/formbook-malware-distribution-campaigns/"}, {"description": "Zscaler Threatlabz. (2025, January 27). Technical Analysis of Xloader Versions 6 and 7 | Part 1. Retrieved March 11, 2025.", "source_name": "Zscaler XLoader 2025", "url": "https://www.zscaler.com/blogs/security-research/technical-analysis-xloader-versions-6-and-7-part-1"}], "id": "relationship--945108e9-bf13-48ed-bdf5-a7888d0f9fba", "modified": "2026-04-29T14:23:06.127Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9c629607-03e4-4952-b481-2d54221d2783", "spec_version": "2.1", "target_ref": "attack-pattern--58a3e6aa-4453-4cc8-a51f-4befe80b31a8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19843', 0, 133, '09-mitre-attack', 'retrieved', '7A87CD0AC5019F7F3194C6ACDB3777783410B7166ADFE816DED16B3263D31DE5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
