VALUES ('doc-09-mitre-attack-p0-19846', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-11T19:27:49.495Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XLoader](https://attack.mitre.org/software/S1207) can initiate a system reboot or shutdown.(Citation: Google XLoader 2017)", "external_references": [{"description": "Nart Villeneuve, Randi Eitzman, Sandor Nemes & Tyler Dean, Google Cloud. (2017, October 5). Significant FormBook Distribution Campaigns Impacting the U.S. and South Korea. Retrieved March 11, 2025.", "source_name": "Google XLoader 2017", "url": "https://cloud.google.com/blog/topics/threat-intelligence/formbook-malware-distribution-campaigns/"}], "id": "relationship--a506c8b0-572d-470f-b90b-146a81385d13", "modified": "2026-04-29T14:23:06.149Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9c629607-03e4-4952-b481-2d54221d2783", "spec_version": "2.1", "target_ref": "attack-pattern--ff73aa03-0090-4464-83ac-f89e233c02bc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19846', 0, 76, '09-mitre-attack', 'retrieved', 'A1AE4FDA7085804741644C575B1A9DC8F1B4559F16E5011838251DB5BD00F71D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
