VALUES ('doc-09-mitre-attack-p0-19853', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-11T19:52:53.256Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XLoader](https://attack.mitre.org/software/S1207) can collect system information and supported language information from the victim machine.(Citation: Acronis XLoader 2021)", "external_references": [{"description": "Acronis. (2021, November 26). Trojan-as-a-service: From Formbook to XLoader. Retrieved March 11, 2025.", "source_name": "Acronis XLoader 2021", "url": "https://www.acronis.com/en-us/cyber-protection-center/posts/trojan-as-a-service-from-formbook-to-xloader/"}], "id": "relationship--cc8a3a34-1324-4a4d-8557-3c23fad2b07c", "modified": "2026-04-29T14:23:06.205Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9c629607-03e4-4952-b481-2d54221d2783", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19853', 0, 66, '09-mitre-attack', 'retrieved', 'ABCB8D971982EA3336AE939A1352E7EBAADA8DCCCF056D40B7C2D1FBC3363314', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
