VALUES ('doc-09-mitre-attack-p0-19854', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-11T19:51:30.034Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XLoader](https://attack.mitre.org/software/S1207) can utilize hardcoded command and control domain configurations created by the XLoader authors. These are designed to mimic domain registrars and hosting service providers such as Hostinger and Namecheap.(Citation: CheckPoint XLoader 2022)", "external_references": [{"description": "Alexey Bukhteyev & Raman Ladutska, Check Point Research. (2022, May 31). XLoader Botnet: Find Me If You Can. Retrieved March 11, 2025.", "source_name": "CheckPoint XLoader 2022", "url": "https://research.checkpoint.com/2022/xloader-botnet-find-me-if-you-can/"}], "id": "relationship--cca0443d-fc8c-469e-a32e-a1297497337a", "modified": "2026-04-29T14:23:06.205Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9c629607-03e4-4952-b481-2d54221d2783", "spec_version": "2.1", "target_ref": "attack-pattern--40f5caa0-4cb7-4117-89fc-d421bb493df3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19854', 0, 92, '09-mitre-attack', 'retrieved', '1CEE84C7E029B9008D26BEDC6405D5AE0A2F81BB83DAFC818063F39054BFA2EB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
