VALUES ('doc-09-mitre-attack-p0-19855', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-11T19:38:21.245Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XLoader](https://attack.mitre.org/software/S1207) uses various packers, including CyaX, to obfuscate malicious executables.(Citation: Netskope XLoader 2022)", "external_references": [{"description": "Gustavo Palazolo, Netskope. (2022, March 11). New Formbook Campaign Delivered Through Phishing Emails. Retrieved March 11, 2025.", "source_name": "Netskope XLoader 2022", "url": "https://www.netskope.com/blog/new-formbook-campaign-delivered-through-phishing-emails"}], "id": "relationship--e01de877-6987-4264-92f7-bb1d1c195d07", "modified": "2026-04-29T14:23:06.231Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9c629607-03e4-4952-b481-2d54221d2783", "spec_version": "2.1", "target_ref": "attack-pattern--deb98323-e13f-4b0c-8d94-175379069062", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19855', 0, 67, '09-mitre-attack', 'retrieved', '24E9F12C06352B2EBF6BD7672B20E68F03EFFA2D8CEB79E2BAF82C74C7A89CCC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
