VALUES ('doc-09-mitre-attack-p0-19873', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Nidiran](https://attack.mitre.org/software/S0118) can create a new service named msamger (Microsoft Security Accounts Manager), which mimics the legitimate Microsoft database by the same name.(Citation: Symantec Backdoor.Nidiran)(Citation: Microsoft SAM)", "external_references": [{"description": "Sponchioni, R.. (2016, March 11). Backdoor.Nidiran. Retrieved August 3, 2016.", "source_name": "Symantec Backdoor.Nidiran", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2015-120123-5521-99"}, {"description": "Microsoft. (2006, October 30). How to use the SysKey utility to secure the Windows Security Accounts Manager database. Retrieved August 3, 2016.", "source_name": "Microsoft SAM", "url": "https://support.microsoft.com/en-us/kb/310105"}], "id": "relationship--9b1709f3-5062-42f1-82d9-191e66e1d14a", "modified": "2026-04-29T14:23:06.136Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9e9b9415-a7df-406b-b14d-92bfe6809fbe", "spec_version": "2.1", "target_ref": "attack-pattern--7bdca9d5-d500-4d7d-8c52-5fd47baf4c0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19873', 0, 100, '09-mitre-attack', 'retrieved', '3463F68165DB33493D4A72B3A4E5C052835717A54463814BDCE0C793D79D8B23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
