VALUES ('doc-09-mitre-attack-p0-19875', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MoonWind](https://attack.mitre.org/software/S0149) has a keylogger.(Citation: Palo Alto MoonWind March 2017)", "external_references": [{"description": "Miller-Osborn, J. and Grunzweig, J.. (2017, March 30). Trochilus and New MoonWind RATs Used In Attack Against Thai Organizations. Retrieved March 30, 2017.", "source_name": "Palo Alto MoonWind March 2017", "url": "http://researchcenter.paloaltonetworks.com/2017/03/unit42-trochilus-rat-new-moonwind-rat-used-attack-thai-utility-organizations/"}], "id": "relationship--0e58b447-7b3e-404c-b8e5-003734c34574", "modified": "2026-04-29T14:23:05.923Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9ea525fa-b0a9-4dde-84f2-bcea0137b3c1", "spec_version": "2.1", "target_ref": "attack-pattern--09a60ea3-a8d1-4ae5-976e-5783248b72a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19875', 0, 71, '09-mitre-attack', 'retrieved', 'BBA953044C03E8325D293C92551D7D693B65C272DA41E0383E88757675CCFD72', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
