VALUES ('doc-09-mitre-attack-p0-19914', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T17:49:59.603Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": " [HiddenFace](https://attack.mitre.org/software/S9023) can reconfigure Windows firewalls to enable communication by adding a rule named “Cortana” to allow inbound connection to TCP/47000.(Citation: ESET HiddenFace 2024)(Citation: Trend Micro Earth Kasha NOV 2024)", "external_references": [{"description": "Breitenbacher, D. (2024). Unmasking HiddenFace. Retrieved April 17, 2026.", "source_name": "ESET HiddenFace 2024", "url": "https://jsac.jpcert.or.jp/archive/2024/pdf/JSAC2024_2_8_Breitenbacher_en.pdf"}, {"description": "Trend Micro. (2024, November 19). Spot the Difference: Earth Kasha''s New LODEINFO Campaign And The Correlation Analysis With The APT10 Umbrella. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/lodeinfo-campaign-of-earth-kasha.html"}], "id": "relationship--fbb495aa-063b-45c4-829a-a9499a66e525", "modified": "2026-04-29T14:23:06.267Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9edc41d1-a13d-4acf-b400-d47fb2f6809d", "spec_version": "2.1", "target_ref": "attack-pattern--291ede6c-1473-454c-b614-5ac5ea63c987", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19914', 0, 111, '09-mitre-attack', 'retrieved', '94385EE25CF07EFF18C8D819FD1A3CD3188AEAB7C7FA25E83F17D32DB4D943F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
