VALUES ('doc-09-mitre-attack-p0-19921', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-12T15:47:03.537Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CorKLOG](https://attack.mitre.org/software/S1235) has achieved persistence through the creation of a scheduled task named TableInputServices by using the command `schtasks /create /tn TabletlnputServices /tr /sc minute /mo 10 /f`.(Citation: Zscaler PAKLOG CorkLog SplatCloak Splatdropper April 2025)", "external_references": [{"description": "Sudeep Singh. (2025, April 16). Latest Mustang Panda Arsenal: PAKLOG, CorKLOG, and SplatCloak | P2. Retrieved September 12, 2025.", "source_name": "Zscaler PAKLOG CorkLog SplatCloak Splatdropper April 2025", "url": "https://www.zscaler.com/blogs/security-research/latest-mustang-panda-arsenal-paklog-corklog-and-splatcloak-p2"}], "id": "relationship--8dafeeb9-067e-4118-9d96-ee8875711096", "modified": "2026-04-29T14:23:06.118Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--9fd4e24b-3b12-4c7c-925f-226e2e3c3758", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19921', 0, 94, '09-mitre-attack', 'retrieved', 'FFBC6293BE66E69537339C53272651CC13F7486895A69045DC841D98FFBDF2B6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
