VALUES ('doc-09-mitre-attack-p0-19930', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-29T13:12:00.941Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ryuk](https://attack.mitre.org/software/S0446) can use stolen domain admin accounts to move laterally within a victim domain.(Citation: ANSSI RYUK RANSOMWARE)", "external_references": [{"description": "ANSSI. (2021, February 25). RYUK RANSOMWARE. Retrieved March 29, 2021.", "source_name": "ANSSI RYUK RANSOMWARE", "url": "https://www.cert.ssi.gouv.fr/uploads/CERTFR-2021-CTI-006.pdf"}], "id": "relationship--561f217e-8392-40b3-84a7-29fbd1399d88", "modified": "2026-04-29T14:23:06.043Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a020a61c-423f-4195-8c46-ba1d21abba37", "spec_version": "2.1", "target_ref": "attack-pattern--c3d4bdd9-2cfe-4a80-9d0c-07a29ecdce8f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19930', 0, 64, '09-mitre-attack', 'retrieved', 'F087570F4835F050B0D92A232B777AFBE3978F36C7E749D0962C39751CB097F5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
