VALUES ('doc-09-mitre-attack-p0-19931', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-14T14:27:31.195Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ryuk](https://attack.mitre.org/software/S0446) has used cmd.exe to create a Registry entry to establish persistence.(Citation: CrowdStrike Ryuk January 2019)", "external_references": [{"description": "Hanel, A. (2019, January 10). Big Game Hunting with Ryuk: Another Lucrative Targeted Ransomware. Retrieved May 12, 2020.", "source_name": "CrowdStrike Ryuk January 2019", "url": "https://www.crowdstrike.com/blog/big-game-hunting-with-ryuk-another-lucrative-targeted-ransomware/"}], "id": "relationship--5a7aeb29-4f1c-43e4-9efa-dc6fb812f281", "modified": "2026-04-29T14:23:06.049Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a020a61c-423f-4195-8c46-ba1d21abba37", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19931', 0, 72, '09-mitre-attack', 'retrieved', '02166201F255C7D4CD0662EBFEE7461A5FDE9C02979135EB108DC2991BE6FCE7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
