VALUES ('doc-09-mitre-attack-p0-19932', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-14T13:59:58.133Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ryuk](https://attack.mitre.org/software/S0446) has constructed legitimate appearing installation folder paths by calling GetWindowsDirectoryW and then inserting a null byte at the fourth character of the path. For Windows Vista or higher, the path would appear as C:\\Users\\Public .(Citation: CrowdStrike Ryuk January 2019)", "external_references": [{"description": "Hanel, A. (2019, January 10). Big Game Hunting with Ryuk: Another Lucrative Targeted Ransomware. Retrieved May 12, 2020.", "source_name": "CrowdStrike Ryuk January 2019", "url": "https://www.crowdstrike.com/blog/big-game-hunting-with-ryuk-another-lucrative-targeted-ransomware/"}], "id": "relationship--5cba4a5e-c005-495d-9cd6-60794d9b3247", "modified": "2026-04-29T14:23:06.052Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a020a61c-423f-4195-8c46-ba1d21abba37", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19932', 0, 96, '09-mitre-attack', 'retrieved', 'F59117A38592985CA1ABE5A7288897ACAF8EE9C5D0D0CB4A5C66C72BC319200A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
