VALUES ('doc-09-mitre-attack-p0-19935', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-14T15:09:48.789Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ryuk](https://attack.mitre.org/software/S0446) has stopped services related to anti-virus.(Citation: FireEye Ryuk and Trickbot January 2019)", "external_references": [{"description": "Goody, K., et al (2019, January 11). A Nasty Trick: From Credential Theft Malware to Business Disruption. Retrieved May 12, 2020.", "source_name": "FireEye Ryuk and Trickbot January 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/01/a-nasty-trick-from-credential-theft-malware-to-business-disruption.html"}], "id": "relationship--976be974-62dc-462e-9a5c-2b389d177d3c", "modified": "2026-04-29T14:23:06.131Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a020a61c-423f-4195-8c46-ba1d21abba37", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19935', 0, 74, '09-mitre-attack', 'retrieved', '52FD37C0C4094C680EE60DCECC6DFEFE9012A1FFD1670AE825D201FBD7D31531', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
