VALUES ('doc-09-mitre-attack-p0-19936', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-29T13:01:52.203Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ryuk](https://attack.mitre.org/software/S0446) can remotely create a scheduled task to execute itself on a system.(Citation: ANSSI RYUK RANSOMWARE)", "external_references": [{"description": "ANSSI. (2021, February 25). RYUK RANSOMWARE. Retrieved March 29, 2021.", "source_name": "ANSSI RYUK RANSOMWARE", "url": "https://www.cert.ssi.gouv.fr/uploads/CERTFR-2021-CTI-006.pdf"}], "id": "relationship--9a99890c-dea1-4ef6-8605-fd4c43f6e37c", "modified": "2026-04-29T14:23:06.136Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a020a61c-423f-4195-8c46-ba1d21abba37", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19936', 0, 63, '09-mitre-attack', 'retrieved', '986FB7247FE2B4846AB9063D7CA072DB1B79FB516ABF9D3B83BDB3D64306D972', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
