VALUES ('doc-09-mitre-attack-p0-19941', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-30T18:26:25.083Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ryuk](https://attack.mitre.org/software/S0446) can create .dll files that actually contain a Rich Text File format document.(Citation: ANSSI RYUK RANSOMWARE)", "external_references": [{"description": "ANSSI. (2021, February 25). RYUK RANSOMWARE. Retrieved March 29, 2021.", "source_name": "ANSSI RYUK RANSOMWARE", "url": "https://www.cert.ssi.gouv.fr/uploads/CERTFR-2021-CTI-006.pdf"}], "id": "relationship--df3548d1-800d-4d18-8566-3a5fe925a2ef", "modified": "2026-04-29T14:23:06.230Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a020a61c-423f-4195-8c46-ba1d21abba37", "spec_version": "2.1", "target_ref": "attack-pattern--42e8de7b-37b2-4258-905a-6897815e58e0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19941', 0, 64, '09-mitre-attack', 'retrieved', '01B6C8A8729D454D2A431026ABD9A2B5E8E725D00B375D76DDDD0208C776F08B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
