VALUES ('doc-09-mitre-attack-p0-19953', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-25T18:51:00.268Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HermeticWiper](https://attack.mitre.org/software/S0697) has the ability to set the `HKLM:\\SYSTEM\\\\CurrentControlSet\\\\Control\\\\CrashControl\\CrashDumpEnabled` Registry key to `0` in order to disable crash dumps.(Citation: SentinelOne Hermetic Wiper February 2022)(Citation: Crowdstrike DriveSlayer February 2022)(Citation: Qualys Hermetic Wiper March 2022)", "external_references": [{"description": "Guerrero-Saade, J. (2022, February 23). HermeticWiper | New Destructive Malware Used In Cyber Attacks on Ukraine. Retrieved March 25, 2022.", "source_name": "SentinelOne Hermetic Wiper February 2022", "url": "https://www.sentinelone.com/labs/hermetic-wiper-ukraine-under-attack"}, {"description": "Thomas, W. et al. (2022, February 25). CrowdStrike Falcon Protects from New Wiper Malware Used in Ukraine Cyberattacks. Retrieved March 25, 2022.", "source_name": "Crowdstrike DriveSlayer February 2022", "url": "https://www.crowdstrike.com/blog/how-crowdstrike-falcon-protects-against-wiper-malware-used-in-ukraine-attacks/"}, {"description": "Dani, M. (2022, March 1). Ukrainian Targets Hit by HermeticWiper, New Datawiper Malware. Retrieved March 25, 2022.", "source_name": "Qualys Hermetic Wiper March 2022", "url": "https://blog.qualys.com/vulnerabilities-threat-research/2022/03/01/ukrainian-targets-hit-by-hermeticwiper-new-datawiper-malware"}], "id": "relationship--0e44aa81-e454-4274-9fba-07fe3d3e3a0c", "modified": "2026-04-29T14:23:05.923Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a0ab8a96-40c9-4483-8a54-3fafa6d6007a", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19953', 0, 147, '09-mitre-attack', 'retrieved', 'FC268D8D1E9545E639A79F3FAE8B064AE33E798CE9909F121006AA869DBB6701', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
