VALUES ('doc-09-mitre-attack-p0-19955', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-25T20:21:17.698Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HermeticWiper](https://attack.mitre.org/software/S0697) has the ability to deploy through an infected system''s default domain policy.(Citation: ESET Hermetic Wizard March 2022)", "external_references": [{"description": "ESET. (2022, March 1). IsaacWiper and HermeticWizard: New wiper and worm targetingUkraine. Retrieved April 10, 2022.", "source_name": "ESET Hermetic Wizard March 2022", "url": "https://www.welivesecurity.com/2022/03/01/isaacwiper-hermeticwizard-wiper-worm-targeting-ukraine"}], "id": "relationship--2b7d386f-57b6-4ed2-a5bf-bcc20c92c95b", "modified": "2026-04-29T14:23:05.964Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a0ab8a96-40c9-4483-8a54-3fafa6d6007a", "spec_version": "2.1", "target_ref": "attack-pattern--5d2be8b9-d24c-4e98-83bf-2f5f79477163", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19955', 0, 73, '09-mitre-attack', 'retrieved', '53F1CA6DAD5E42B3AE80D71AB3415A3C753D5F434F20F30D554A7D49D3CA1937', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
