VALUES ('doc-09-mitre-attack-p0-19957', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-25T19:14:18.195Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [HermeticWiper](https://attack.mitre.org/software/S0697) executable has been signed with a legitimate certificate issued to Hermetica Digital Ltd.(Citation: Symantec Ukraine Wipers February 2022)(Citation: Crowdstrike DriveSlayer February 2022)(Citation: ESET Hermetic Wiper February 2022)(Citation: Qualys Hermetic Wiper March 2022)", "external_references": [{"description": "Symantec Threat Hunter Team. (2022, February 24). Ukraine: Disk-wiping Attacks Precede Russian Invasion. Retrieved March 25, 2022.", "source_name": "Symantec Ukraine Wipers February 2022", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/ukraine-wiper-malware-russia"}, {"description": "Thomas, W. et al. (2022, February 25). CrowdStrike Falcon Protects from New Wiper Malware Used in Ukraine Cyberattacks. Retrieved March 25, 2022.", "source_name": "Crowdstrike DriveSlayer February 2022", "url": "https://www.crowdstrike.com/blog/how-crowdstrike-falcon-protects-against-wiper-malware-used-in-ukraine-attacks/"}, {"description": "ESET. (2022, February 24). HermeticWiper: New data wiping malware hits Ukraine. Retrieved March 25, 2022.", "source_name": "ESET Hermetic Wiper February 2022", "url": "https://www.welivesecurity.com/2022/02/24/hermeticwiper-new-data-wiping-malware-hits-ukraine"}, {"description": "Dani, M. (2022, March 1). Ukrainian Targets Hit by HermeticWiper, New Datawiper Malware. Retrieved March 25, 2022.", "source_name": "Qualys Hermetic Wiper March 2022", "url": "https://blog.qualys.com/vulnerabilities-threat-research/2022/03/01/ukrainian-targets-hit-by-hermeticwiper-new-datawiper-malware"}], "id": "relationship--415f38f8-d490-461a-9a40-968f8cd2bd8b", "modified": "2026-04-29T14:23:06.014Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a0ab8a96-40c9-4483-8a54-3fafa6d6007a", "spec_version": "2.1", "target_ref": "attack-pattern--32901740-b42c-4fdd-bc02-345b5dc57082", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19957', 0, 170, '09-mitre-attack', 'retrieved', '3F8D65BD532600E3F8E16F2B1FC99C97405E4AFBB718CD6B54DDFFD2AE308FC6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
