VALUES ('doc-09-mitre-attack-p0-20054', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-29T19:00:34.070Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockBit 2.0](https://attack.mitre.org/software/S1199) can disable firewall rules and anti-malware and monitoring software including Windows Defender.(Citation: FBI Lockbit 2.0 FEB 2022)(Citation: Palo Alto Lockbit 2.0 JUN 2022)", "external_references": [{"description": "Elsad, A. et al. (2022, June 9). LockBit 2.0: How This RaaS Operates and How to Protect Against It. Retrieved January 24, 2025.", "source_name": "Palo Alto Lockbit 2.0 JUN 2022", "url": "https://unit42.paloaltonetworks.com/lockbit-2-ransomware/"}, {"description": "FBI. (2022, February 4). Indicators of Compromise Associated with LockBit 2.0 Ransomware. Retrieved January 24, 2025.", "source_name": "FBI Lockbit 2.0 FEB 2022", "url": "https://www.ic3.gov/CSA/2022/220204.pdf"}], "id": "relationship--36f687d3-8052-4009-836d-8b796a1fcf71", "modified": "2026-04-29T14:23:05.995Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a4578560-42cf-4075-9fa2-056f0058c881", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20054', 0, 113, '09-mitre-attack', 'retrieved', '652423EBC71E90B9B5C8BAA1C929D44DA992A085AEDDCD4EDF47B5F62F800B65', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
