VALUES ('doc-09-mitre-attack-p0-20061', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-27T19:36:44.339Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockBit 2.0](https://attack.mitre.org/software/S1199) can determine if a running process has administrative privileges and terminate processes that interfere with encryption or exfiltration.(Citation: FBI Lockbit 2.0 FEB 2022)(Citation: SentinelOne LockBit 2.0)", "external_references": [{"description": "FBI. (2022, February 4). Indicators of Compromise Associated with LockBit 2.0 Ransomware. Retrieved January 24, 2025.", "source_name": "FBI Lockbit 2.0 FEB 2022", "url": "https://www.ic3.gov/CSA/2022/220204.pdf"}, {"description": "SentinelOne. (n.d.). LockBit 2.0: In-Depth Analysis, Detection, Mitigation, and Removal. Retrieved January 24, 2025.", "source_name": "SentinelOne LockBit 2.0", "url": "https://www.sentinelone.com/anthology/lockbit-2-0/"}], "id": "relationship--767f436a-6979-456b-8d2d-b8c8a6b86446", "modified": "2026-04-29T14:23:06.087Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a4578560-42cf-4075-9fa2-056f0058c881", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20061', 0, 104, '09-mitre-attack', 'retrieved', 'C1C526DC3F55AC5E0EE626325974E2010C07D5E21A353BD6F4F9905729861D94', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
