VALUES ('doc-09-mitre-attack-p0-20062', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-29T18:41:33.687Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockBit 2.0](https://attack.mitre.org/software/S1199) can exclude files associated with core system functions from encryption.(Citation: FBI Lockbit 2.0 FEB 2022)", "external_references": [{"description": "FBI. (2022, February 4). Indicators of Compromise Associated with LockBit 2.0 Ransomware. Retrieved January 24, 2025.", "source_name": "FBI Lockbit 2.0 FEB 2022", "url": "https://www.ic3.gov/CSA/2022/220204.pdf"}], "id": "relationship--784e4454-00c9-482e-a8a8-d5db7b034d3c", "modified": "2026-04-29T14:23:06.089Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a4578560-42cf-4075-9fa2-056f0058c881", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20062', 0, 72, '09-mitre-attack', 'retrieved', '9A8F2E7BD709887A64B754D7BFE5BC0E853024F939492D9770D2943972BCBC42', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
