VALUES ('doc-09-mitre-attack-p0-20080', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T18:39:48.467Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Zebrocy](https://attack.mitre.org/software/S0251) uses the tasklist and wmic process get Capture, ExecutablePath commands to gather the processes running on the system.(Citation: Unit42 Cannon Nov 2018)(Citation: ESET Zebrocy Nov 2018)(Citation: Unit42 Sofacy Dec 2018)(Citation: ESET Zebrocy May 2019)(Citation: Accenture SNAKEMACKEREL Nov 2018)", "external_references": [{"description": "Falcone, R., Lee, B. (2018, November 20). Sofacy Continues Global Attacks and Wheels Out New ‘Cannon’ Trojan. Retrieved November 26, 2018.", "source_name": "Unit42 Cannon Nov 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/11/unit42-sofacy-continues-global-attacks-wheels-new-cannon-trojan/"}, {"description": "ESET. (2018, November 20). Sednit: What’s going on with Zebrocy?. Retrieved February 12, 2019.", "source_name": "ESET Zebrocy Nov 2018", "url": "https://www.welivesecurity.com/2018/11/20/sednit-whats-going-zebrocy/"}, {"description": "Lee, B., Falcone, R. (2018, December 12). Dear Joohn: The Sofacy Group’s Global Campaign. Retrieved April 19, 2019.", "source_name": "Unit42 Sofacy Dec 2018", "url": "https://unit42.paloaltonetworks.com/dear-joohn-sofacy-groups-global-campaign/"}, {"description": "ESET Research. (2019, May 22). A journey to Zebrocy land. Retrieved June 20, 2019.", "source_name": "ESET Zebrocy May 2019", "url": "https://www.welivesecurity.com/2019/05/22/journey-zebrocy-land/"}, {"description": "Accenture Security. (2018, November 29). SNAKEMACKEREL. Retrieved April 15, 2019.", "source_name": "Accenture SNAKEMACKEREL Nov 2018", "url": "https://www.accenture.com/t20181129T203820Z__w__/us-en/_acnmedia/PDF-90/Accenture-snakemackerel-delivers-zekapab-malware.pdf#zoom=50"}], "id": "relationship--1051f320-91fa-4f89-8abe-a851a56e18a7", "modified": "202