VALUES ('doc-09-mitre-attack-p0-20087', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T18:39:48.418Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Zebrocy](https://attack.mitre.org/software/S0251) installs an application-defined Windows hook to get notified when a network drive has been attached, so it can then use the hook to call its RecordToFile file stealing method.(Citation: Securelist Sofacy Feb 2018)", "external_references": [{"description": "Kaspersky Lab''s Global Research & Analysis Team. (2018, February 20). A Slice of 2017 Sofacy Activity. Retrieved November 27, 2018.", "source_name": "Securelist Sofacy Feb 2018", "url": "https://securelist.com/a-slice-of-2017-sofacy-activity/83930/"}], "id": "relationship--4f550078-32b1-4abb-aa90-0e9fb7cc45f9", "modified": "2026-04-29T14:23:06.033Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a4f57468-fbd5-49e4-8476-52088220b92d", "spec_version": "2.1", "target_ref": "attack-pattern--f5946b5e-9408-485f-a7f7-b5efc88909b6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20087', 0, 92, '09-mitre-attack', 'retrieved', '1953D16EA2900CD658773BCDB0B104DB8153CB6817F67834DE50161FEE6B4C99', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
