VALUES ('doc-09-mitre-attack-p0-20093', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T18:39:48.457Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Zebrocy](https://attack.mitre.org/software/S0251) searches for files that are 60mb and less and contain the following extensions: .doc, .docx, .xls, .xlsx, .ppt, .pptx, .exe, .zip, and .rar. [Zebrocy](https://attack.mitre.org/software/S0251) also runs the echo %APPDATA% command to list the contents of the directory.(Citation: Securelist Sofacy Feb 2018)(Citation: ESET Zebrocy Nov 2018)(Citation: ESET Zebrocy May 2019) [Zebrocy](https://attack.mitre.org/software/S0251) can obtain the current execution path as well as perform drive enumeration.(Citation: Accenture SNAKEMACKEREL Nov 2018)(Citation: CISA Zebrocy Oct 2020) ", "external_references": [{"description": "Kaspersky Lab''s Global Research & Analysis Team. (2018, February 20). A Slice of 2017 Sofacy Activity. Retrieved November 27, 2018.", "source_name": "Securelist Sofacy Feb 2018", "url": "https://securelist.com/a-slice-of-2017-sofacy-activity/83930/"}, {"description": "ESET. (2018, November 20). Sednit: What’s going on with Zebrocy?. Retrieved February 12, 2019.", "source_name": "ESET Zebrocy Nov 2018", "url": "https://www.welivesecurity.com/2018/11/20/sednit-whats-going-zebrocy/"}, {"description": "ESET Research. (2019, May 22). A journey to Zebrocy land. Retrieved June 20, 2019.", "source_name": "ESET Zebrocy May 2019", "url": "https://www.welivesecurity.com/2019/05/22/journey-zebrocy-land/"}, {"description": "Accenture Security. (2018, November 29). SNAKEMACKEREL. Retrieved April 15, 2019.", "source_name": "Accenture SNAKEMACKEREL Nov 2018", "url": "https://www.accenture.com/t20181129T203820Z__w__/us-en/_acnmedia/PDF-90/Accenture-snakemackerel-delivers-zekapab-malware.pdf#zoom=50"}, {"description": "CISA. (2020, October 29). Malware Analysis Report (AR20-303B). Retrieved December 9, 2020.", "source_name": "CISA Zebrocy Oct 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-303b"}], "id": "relationship--86b7bab7-a1d6-4820-be55-c379f3967f1a", "modified": "2026-04-29T14:23:06.109Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a4f57468-fbd5-49e4-8476-52088220b92d", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20093', 0, 212, '09-mitre-attack', 'retrieved', 'CF5412CB537994E2B4D30BF113D35D96F149C30ADD76192E335095BFD23C8DC9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
