VALUES ('doc-09-mitre-attack-p0-20123', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FinFisher](https://attack.mitre.org/software/S0182) uses token manipulation with NtFilterToken as part of UAC bypass.(Citation: FinFisher Citation)(Citation: Microsoft FinFisher March 2018)", "external_references": [{"description": "Allievi, A.,Flori, E. (2018, March 01). FinFisher exposed: A researcher’s tale of defeating traps, tricks, and complex virtual machines. Retrieved July 9, 2018.", "source_name": "Microsoft FinFisher March 2018", "url": "https://cloudblogs.microsoft.com/microsoftsecure/2018/03/01/finfisher-exposed-a-researchers-tale-of-defeating-traps-tricks-and-complex-virtual-machines/"}, {"description": "FinFisher. (n.d.). Retrieved September 12, 2024.", "source_name": "FinFisher Citation", "url": "https://web.archive.org/web/20171222050934/http://www.finfisher.com/FinFisher/index.html"}], "id": "relationship--0b10d358-b59f-4fc0-8eaf-37352be9c80b", "modified": "2026-04-29T14:23:05.918Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a5528622-3a8a-4633-86ce-8cdaf8423858", "spec_version": "2.1", "target_ref": "attack-pattern--86850eff-2729-40c3-b85e-c4af26da4a2d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20123', 0, 90, '09-mitre-attack', 'retrieved', '29BCFD820AA4492D401E86DCC2845B478B34DE8C8E3C846D74C824F923693395', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
