VALUES ('doc-09-mitre-attack-p0-20185', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-28T21:03:22.425Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CrossRAT](https://attack.mitre.org/software/S0235) can use an XDG Autostart to establish persistence.(Citation: Red Canary Netwire Linux 2022)", "external_references": [{"description": "TONY LAMBERT. (2022, June 7). Trapping the Netwire RAT on Linux. Retrieved September 28, 2023.", "source_name": "Red Canary Netwire Linux 2022", "url": "https://redcanary.com/blog/netwire-remote-access-trojan-on-linux/"}], "id": "relationship--c848ea14-292b-4ad8-ab58-70b26b023275", "modified": "2026-04-29T14:23:06.199Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a5e91d50-24fa-44ec-9894-39a88f658cea", "spec_version": "2.1", "target_ref": "attack-pattern--e0232cb0-ded5-4c2e-9dc7-2893142a5c11", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20185', 0, 68, '09-mitre-attack', 'retrieved', '3075378DB92323B0AAC362AE7220C1193A72A3EBBF78492BF1DD07FA7783D58C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
