VALUES ('doc-09-mitre-attack-p0-20190', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OwaAuth](https://attack.mitre.org/software/S0072) has a command to timestop a file or directory.(Citation: Dell TG-3390)", "external_references": [{"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, August 5). Threat Group-3390 Targets Organizations for Cyberespionage. Retrieved August 18, 2018.", "source_name": "Dell TG-3390", "url": "https://www.secureworks.com/research/threat-group-3390-targets-organizations-for-cyberespionage"}], "id": "relationship--37804b22-63b4-4b24-846e-6541688d9213", "modified": "2026-04-29T14:23:05.996Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a60657fa-e2e7-4f8f-8128-a882534ae8c5", "spec_version": "2.1", "target_ref": "attack-pattern--47f2d673-ca62-47e9-929b-1b0be9657611", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20190', 0, 68, '09-mitre-attack', 'retrieved', '3C645E32EAB3BEFAEFDB86FD9EF71FF7F0C73575C6B22E4EBFAA84424B5AC8B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
