VALUES ('doc-09-mitre-attack-p0-20206', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-06T18:40:38.198Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cobalt Strike](https://attack.mitre.org/software/S0154) can start a VNC-based remote desktop server and tunnel the connection through the already established C2 channel.(Citation: cobaltstrike manual)(Citation: Cybereason Bumblebee August 2022)", "external_references": [{"description": "Cybereason. (2022, August 17). Bumblebee Loader – The High Road to Enterprise Domain Control. Retrieved August 29, 2022.", "source_name": "Cybereason Bumblebee August 2022", "url": "https://www.cybereason.com/blog/threat-analysis-report-bumblebee-loader-the-high-road-to-enterprise-domain-control"}, {"description": "Strategic Cyber LLC. (2017, March 14). Cobalt Strike Manual. Retrieved May 24, 2017.", "source_name": "cobaltstrike manual", "url": "https://web.archive.org/web/20210825130434/https://cobaltstrike.com/downloads/csmanual38.pdf"}], "id": "relationship--094a2284-eeab-47fd-b6fb-6351d98330aa", "modified": "2026-04-29T14:23:05.916Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a7881f21-e978-4fe4-af56-92c9416a2616", "spec_version": "2.1", "target_ref": "attack-pattern--eb062747-2193-45de-8fa2-e62549c37ddf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20206', 0, 100, '09-mitre-attack', 'retrieved', '37E6F36EC1B792A6EA9A31ABB3ABBC2ADD90AF876ECD8E3E645FA43B9623E27B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
