VALUES ('doc-09-mitre-attack-p0-20228', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-20T15:05:36.346Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cobalt Strike](https://attack.mitre.org/software/S0154) can leverage the HTTP protocol for C2 communication, while hiding the actual data in either an HTTP header, URI parameter, the transaction body, or appending it to the URI.(Citation: Cobalt Strike Manual 4.3 November 2020) [Cobalt Strike](https://attack.mitre.org/software/S0154) has also added Host: ocsp.verisign.com to HTTP headers to mimic Online Certificate Status Protocol (OCSP) traffic.(Citation: Cisco Talos Qilin Ransomware OCT 2025)", "external_references": [{"description": "Strategic Cyber LLC. (2020, November 5). Cobalt Strike: Advanced Threat Tactics for Penetration Testers. Retrieved April 13, 2021.", "source_name": "Cobalt Strike Manual 4.3 November 2020", "url": "https://web.archive.org/web/20210708035426/https://www.cobaltstrike.com/downloads/csmanual43.pdf"}, {"description": "Takeda, T. et al. (2025, October 26). Uncovering Qilin attack methods exposed through multiple cases. Retrieved March 26, 2026.", "source_name": "Cisco Talos Qilin Ransomware OCT 2025", "url": "https://blog.talosintelligence.com/uncovering-qilin-attack-methods-exposed-through-multiple-cases/"}], "id": "relationship--5179f874-72fb-4743-bd51-3f3fdb660038", "modified": "2026-04-29T14:23:06.037Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a7881f21-e978-4fe4-af56-92c9416a2616", "spec_version": "2.1", "target_ref": "attack-pattern--c325b232-d5bc-4dde-a3ec-71f3db9e8adc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20228', 0, 148, '09-mitre-attack', 'retrieved', 'B41D4A2E4A6CA6AA0898EFE6007DD8532211FC30F34515A550963D99C94BE87A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
