VALUES ('doc-09-mitre-attack-p0-20246', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-07T14:48:18.578Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cobalt Strike](https://attack.mitre.org/software/S0154) can query HKEY_CURRENT_USER\\Software\\Microsoft\\Office\\ \\Excel\\Security\\AccessVBOM\\ to determine if the security setting for restricting default programmatic access is enabled.(Citation: Talos Cobalt Strike September 2020)(Citation: Cobalt Strike Manual 4.3 November 2020)", "external_references": [{"description": "Mavis, N. (2020, September 21). The Art and Science of Detecting Cobalt Strike. Retrieved September 12, 2024.", "source_name": "Talos Cobalt Strike September 2020", "url": "https://web.archive.org/web/20210219195905/https://talos-intelligence-site.s3.amazonaws.com/production/document_files/files/000/095/031/original/Talos_Cobalt_Strike.pdf"}, {"description": "Strategic Cyber LLC. (2020, November 5). Cobalt Strike: Advanced Threat Tactics for Penetration Testers. Retrieved April 13, 2021.", "source_name": "Cobalt Strike Manual 4.3 November 2020", "url": "https://web.archive.org/web/20210708035426/https://www.cobaltstrike.com/downloads/csmanual43.pdf"}], "id": "relationship--8e12d3f8-6c2b-4622-889e-63c9abcff04b", "modified": "2026-04-29T14:23:06.119Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a7881f21-e978-4fe4-af56-92c9416a2616", "spec_version": "2.1", "target_ref": "attack-pattern--c32f7008-9fea-41f7-8366-5eb9b74bd896", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20246', 0, 114, '09-mitre-attack', 'retrieved', 'EAAFAC6A8F0C246B84691C94E26C8C4AD62D802850AA7D18248169F0EBC8F4D9', 'v1', '{"source_id": "09-mitre-attack", "versio