VALUES ('doc-09-mitre-attack-p0-20253', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-07T14:29:47.538Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cobalt Strike](https://attack.mitre.org/software/S0154) can use RSA asymmetric encryption with PKCS1 padding to encrypt data sent to the C2 server.(Citation: Talos Cobalt Strike September 2020)", "external_references": [{"description": "Mavis, N. (2020, September 21). The Art and Science of Detecting Cobalt Strike. Retrieved September 12, 2024.", "source_name": "Talos Cobalt Strike September 2020", "url": "https://web.archive.org/web/20210219195905/https://talos-intelligence-site.s3.amazonaws.com/production/document_files/files/000/095/031/original/Talos_Cobalt_Strike.pdf"}], "id": "relationship--a3aa78fe-28c9-44e8-a0a3-0f84c087b5e0", "modified": "2026-04-29T14:23:06.148Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a7881f21-e978-4fe4-af56-92c9416a2616", "spec_version": "2.1", "target_ref": "attack-pattern--bf176076-b789-408e-8cba-7275e81c0ada", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20253', 0, 79, '09-mitre-attack', 'retrieved', '44287AC2FC1BBEE0A8F0B1E6E8AFF73BC96E68B4A18A1383B53A9422B612F804', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
