VALUES ('doc-09-mitre-attack-p0-20254', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-06T18:40:38.191Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cobalt Strike](https://attack.mitre.org/software/S0154) can perform browser pivoting and inject into a user''s browser to inherit cookies, authenticated HTTP sessions, and client SSL certificates.(Citation: cobaltstrike manual)(Citation: Cobalt Strike Manual 4.3 November 2020)", "external_references": [{"description": "Strategic Cyber LLC. (2017, March 14). Cobalt Strike Manual. Retrieved May 24, 2017.", "source_name": "cobaltstrike manual", "url": "https://web.archive.org/web/20210825130434/https://cobaltstrike.com/downloads/csmanual38.pdf"}, {"description": "Strategic Cyber LLC. (2020, November 5). Cobalt Strike: Advanced Threat Tactics for Penetration Testers. Retrieved April 13, 2021.", "source_name": "Cobalt Strike Manual 4.3 November 2020", "url": "https://web.archive.org/web/20210708035426/https://www.cobaltstrike.com/downloads/csmanual43.pdf"}], "id": "relationship--ad7f635b-7775-4706-8577-eee00612c996", "modified": "2026-04-29T14:23:06.161Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a7881f21-e978-4fe4-af56-92c9416a2616", "spec_version": "2.1", "target_ref": "attack-pattern--544b0346-29ad-41e1-a808-501bb4193f47", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20254', 0, 107, '09-mitre-attack', 'retrieved', '3AB7096414943B19C27A2605BBE567507F5C13B0E3A05FDB623FD435F2FFC217', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
