VALUES ('doc-09-mitre-attack-p0-20301', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-06T16:56:56.304Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUNBURST](https://attack.mitre.org/software/S0559) collected a list of service names that were hashed using a FNV-1a + XOR algorithm to check against similarly-hashed hardcoded blocklists.(Citation: FireEye SUNBURST Backdoor December 2020)", "external_references": [{"description": "FireEye. (2020, December 13). Highly Evasive Attacker Leverages SolarWinds Supply Chain to Compromise Multiple Global Victims With SUNBURST Backdoor. Retrieved January 4, 2021.", "source_name": "FireEye SUNBURST Backdoor December 2020", "url": "https://www.fireeye.com/blog/threat-research/2020/12/evasive-attacker-leverages-solarwinds-supply-chain-compromises-with-sunburst-backdoor.html"}], "id": "relationship--7e2ceab5-e5ae-4c79-aceb-424d42703e5f", "modified": "2026-04-29T14:23:06.098Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a8839c95-029f-44cf-8f3d-a3cf2039e927", "spec_version": "2.1", "target_ref": "attack-pattern--322bad5a-1c49-4d23-ab79-76d641794afa", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20301', 0, 89, '09-mitre-attack', 'retrieved', '3D5482F65F22EFB331EE3110F8A86B61BA11B2FB3EC77E410DF143C4385A8E8E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
