VALUES ('doc-09-mitre-attack-p0-20312', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-05T22:42:06.146Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUNBURST](https://attack.mitre.org/software/S0559) collected the registry value HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Cryptography\\MachineGuid from compromised hosts.(Citation: FireEye SUNBURST Backdoor December 2020)", "external_references": [{"description": "FireEye. (2020, December 13). Highly Evasive Attacker Leverages SolarWinds Supply Chain to Compromise Multiple Global Victims With SUNBURST Backdoor. Retrieved January 4, 2021.", "source_name": "FireEye SUNBURST Backdoor December 2020", "url": "https://www.fireeye.com/blog/threat-research/2020/12/evasive-attacker-leverages-solarwinds-supply-chain-compromises-with-sunburst-backdoor.html"}], "id": "relationship--cedfb953-2088-4e8d-a21b-57fdfce65337", "modified": "2026-04-29T14:23:06.208Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--a8839c95-029f-44cf-8f3d-a3cf2039e927", "spec_version": "2.1", "target_ref": "attack-pattern--c32f7008-9fea-41f7-8366-5eb9b74bd896", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20312', 0, 76, '09-mitre-attack', 'retrieved', '49D5FD943C9B1CF529502FC20069BB21CD1A47F01BACD0D8B0CC9A645F735B78', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
